  5609	            }
  5610	          }
  5611	        }
  5612	        break;
  5613	
  5614	      case BAG_IF_ELSE:
  5615	        r = tune_tree(NODE_BODY(node), reg, (state | IN_ALT), env);
  5616	        if (r != 0) return r;
  5617	        if (IS_NOT_NULL(en->te.Then)) {
  5618	          r = tune_tree(en->te.Then, reg, (state | IN_ALT), env);
  5619	          if (r != 0) return r;
  5620	        }
  5621	        if (IS_NOT_NULL(en->te.Else))
